css:
/* Complete replacement for the Print Format CSS field.
   A4 portrait. PDF artwork is applied after pagination by proposal_pdf.py. */
html, body {
    margin: 0;
    padding: 0;
    width: auto;
    height: auto;
    background: transparent;
}
.print-format {
    padding: 0 !important;
    /* These are PDF margins, repeated on EVERY page. */
    margin-top: 50mm;
    margin-bottom: 35mm;
    margin-left: 20mm;
    margin-right: 20mm;
    background: transparent !important;
    box-shadow: none !important;
    font-family: Arial, sans-serif;
    font-size: 9pt;
    line-height: 1.4;
    color: #000;
}
/* Frappe turns the top-level rule above into wkhtmltopdf page margins; it reads
   only top-level rules, so this keeps them from applying again inside the page. */
@media print { .print-format { margin: 0 !important; } }
.proposal { font-size: 9pt; line-height: 1.4; }
.proposal-first-page, .proposal-remaining-pages {
    margin: 0;
    padding: 0;
    height: auto;
    overflow: visible;
}
.proposal-remaining-pages { page-break-before: always; break-before: page; }
.keep-section, .proposal-header, .signature {
    page-break-inside: avoid;
    break-inside: avoid-page;
}
.section-title {
    margin: 0;
    padding: 6px 0 3px;
    font-size: 10pt;
    line-height: 1.3;
    font-weight: bold;
    page-break-after: avoid;
    break-after: avoid-page;
    page-break-inside: avoid;
}
.proposal-content { margin: 0; padding: 0; }
.proposal-content p, .proposal-content li {
    orphans: 4;
    widows: 4;
}
/* Saved rich text keeps Quill's editor box (scrolling, 12px padding); print it as plain flow.
   The 2mm right inset absorbs wkhtmltopdf drawing text slightly wider than it laid it out,
   which otherwise clips the last word of full-width lines at the page margin. */
.proposal .ql-editor { height: auto; overflow: visible; padding: 0 2mm 0 0; white-space: normal; line-height: inherit; }
.proposal p { margin: 0 0 4px; }
.proposal ul, .proposal ol { margin: 0 0 4px !important; padding-left: 18px !important; }
.proposal li { margin: 0 0 2px !important; padding: 0 !important; }
.proposal img { max-width: 100%; height: auto; }
.details-table, .pricing-table, .bom-table, .kseb-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 9pt;
}
.details-table td { padding: 3px 0; border: none; }
.ref-label { width: 65px; text-align: left; }
.ref-value { text-align: left; padding-left: 12px !important; }
.ref-date { text-align: right; white-space: nowrap; }
.pricing-table th, .pricing-table td,
.bom-table th, .bom-table td,
.kseb-table th, .kseb-table td {
    border: 1px solid #000;
    padding: 4px 5px;
    vertical-align: top;
    overflow-wrap: break-word;
    word-wrap: break-word;
}
.pricing-table th, .bom-table th, .kseb-table th { text-align: center; font-weight: bold; line-height: 1.2; }
/* Auto widths: the PDF font (DejaVu Sans on the server) is wider than the preview's Arial,
   so amounts and description lines size their columns and System Name takes the rest. */
.pricing-table { table-layout: auto; }
.pricing-table .amount { text-align: right; white-space: nowrap; }
.system-description div { line-height: 1.3; }
.price-summary { margin-top: 5px; }
.price-summary td:first-child, .price-summary th:first-child { text-align: left; }
.actual-item { color: #333; font-size: 8pt; }
.bom-table { table-layout: fixed; page-break-inside: auto; }
.bom-table thead { display: table-header-group; }
.bom-table tbody { page-break-inside: auto; }
.bom-table tr, .pricing-table tr { page-break-inside: avoid; break-inside: avoid-page; }
.bom-table .bom-title { text-align: left; padding: 6px; font-size: 10pt; }
.bom-table td:first-child, .bom-table td:last-child { text-align: center; }
.kseb-table td { width: 50%; }
.kseb-table .kseb-heading { font-weight: bold; }
.material-note { padding-top: 4px; }
.proposal-closing { margin-top: 8px; }
.signature { width: 280px; margin-left: auto; margin-top: 18px; text-align: left; }
.signature-space { height: 14mm; }
/* Browser preview only: illustrative backgrounds for the two HTML sections.
   The browser preview is not a faithful view of wkhtmltopdf's page breaks.
   Actual PDF page backgrounds are stamped by Python, including the last page. */
@media screen {
    .print-format { margin: 0 auto; width: 210mm; max-width: none; }
    .proposal-first-page, .proposal-remaining-pages {
        box-sizing: border-box;
        min-height: 297mm;
        padding: 50mm 20mm 35mm;
        background-position: top center;
        background-size: 210mm 297mm;
    }
    .proposal-first-page { background-image: url('/files/proposal_fp_bg.png'); background-repeat: no-repeat; }
    .proposal-remaining-pages { background-image: url('/files/proposal_bg.png'); background-repeat: repeat-y; }
}
@media print {
    .proposal-first-page, .proposal-remaining-pages { background: none !important; }
}

html:
{# Complete replacement for the Print Format HTML field.
   Backgrounds are applied by proposal_pdf.py after pagination.
   No separate letterhead/footer: the PNGs supply the page artwork. #}
{% macro section(title, content) -%}
{% if content %}
<div class="keep-section">
    <h2 class="section-title">{{ title }}</h2>
    <div class="proposal-content">{{ content | safe }}</div>
</div>
{% endif %}
{%- endmacro %}

{# Empty placeholders let Frappe handle explicit PDF margins. #}
<div id="header-html" class="hidden-pdf"></div>
<div id="footer-html" class="visible-pdf"></div>

{% set first_name = doc.customer_name %}
{% if doc.proposal_to == "Lead" and doc.party %}
    {% set first_name = frappe.db.get_value("Lead", doc.party, "first_name") or doc.customer_name %}
{% endif %}
{# System and material details come from the saved proposal snapshot. #}
{% set system_name = doc.get("system_name") or doc.package_name or "Solar System" %}
{% set brand = doc.get("brand") or "" %}
{% set phase = doc.get("connection_type") or "" %}
{% set grid_type = doc.get("grid_type") or "" %}
{% set structure = "With Structure" if doc.include_structure else "Without Structure" %}
{% set panel_watts = doc.get("panel_capacity_w") or 0 %}
{% set installed_kw = doc.get("actual_capacity_kw") or ((doc.panel_count or 0) * panel_watts / 1000) %}

<div class="proposal">
  <div class="proposal-first-page">
    <div class="proposal-header">
      <table class="details-table">
        <tr>
          <td class="ref-label">Ref. No.</td><td class="ref-value">{{ doc.name }}</td>
          <td class="ref-date">{{ frappe.utils.formatdate(doc.proposal_date) if doc.proposal_date else "" }}</td>
        </tr>
        <tr><td class="ref-label">To</td><td class="ref-value" colspan="2"><strong>{{ first_name }}</strong></td></tr>
      </table>
    </div>

    <div class="keep-section">
      <h2 class="section-title">System Pricing: {{ phase }} {{ brand }} {{ grid_type }} System — {{ structure }}</h2>
      <table class="pricing-table">
        <thead><tr><th style="width:6%">Sl No</th><th style="width:32%">System Name</th><th>Description</th></tr></thead>
        <tbody><tr>
          <td>1</td><td>{{ "%g" | format(doc.capacity_kw or 0) }} kW {{ system_name }}</td>
          <td class="system-description">
            <div>Requested system capacity: {{ "%g" | format(doc.capacity_kw or 0) }} kW</div>
            {% if panel_watts %}<div>Panel capacity: {{ "%g" | format(panel_watts) }} Wp each</div>{% endif %}
            <div>Number of panels: {{ doc.panel_count or 0 }} nos</div>
            {% if doc.get("suggested_panel_count") %}<div>Suggested panel count: {{ doc.suggested_panel_count }} nos</div>{% endif %}
            {% if installed_kw %}<div>Installed panel capacity: {{ "%g" | format(installed_kw) }} kWp</div>{% endif %}
            {% if doc.get("inverter_count") or doc.get("calculation_version") == "Templates v1" %}<div>Number of inverters: {{ doc.inverter_count }} nos</div>{% endif %}
            {% if doc.get("down_run_cabling") %}<div>Downrun cabling: {{ doc.down_run_cabling }}</div>{% endif %}
            {% if doc.get("include_battery") %}<div>Includes battery and applicable battery components</div>{% endif %}
          </td>
        </tr></tbody>
      </table>
      <table class="pricing-table price-summary">
        <tbody>
          <tr><td>Estimated Project Cost</td><td class="amount">₹ {{ frappe.utils.fmt_money(doc.project_cost) }}</td></tr>
          {% if doc.discount %}<tr><td>Discount</td><td class="amount">₹ {{ frappe.utils.fmt_money(doc.discount) }}</td></tr>{% endif %}
          <tr><td>Subsidy Amount</td><td class="amount">₹ {{ frappe.utils.fmt_money(doc.subsidy) }}</td></tr>
          <tr><th>Customer Effective Cost</th><th class="amount">₹ {{ frappe.utils.fmt_money(doc.final_amount) }}</th></tr>
        </tbody>
      </table>
    </div>

    {% if doc.panel_brand or panel_watts %}
    <div class="keep-section">
      <h2 class="section-title">Panel Make</h2>
      <div class="panel-make">{{ doc.panel_brand or "" }}{% if panel_watts %} — {{ "%g" | format(panel_watts) }} Wp panels{% endif %}</div>
    </div>
    {% endif %}

    {% set warranty = frappe.db.get_all("Solar Proposal Content", filters={"title": ["like", "Warranty%"], "brand": brand, "enabled": 1}, fields=["content"]) %}
    {% if warranty %}
    <div class="keep-section">
      <h2 class="section-title">Warranty</h2>
      {% for item in warranty %}<div class="proposal-content">{{ item.content or "" | safe }}</div>{% endfor %}
    </div>
    {% endif %}

    {% set payment_terms = frappe.db.get_value("Solar Proposal Content", {"title": "Payment Terms", "enabled": 1}, "content") %}
    {# Two columns: payment schedule | KSEB charges. The saved list is split at the
       whole <li> holding "KSEB Charges" and both halves get their list/div closed
       again, so the HTML stays balanced. Without that item it renders as one block. #}
    {% set kseb_at = (payment_terms or "").find("KSEB Charges") %}
    {% set item_at = (payment_terms or "")[:kseb_at].rfind("<li") if kseb_at > 0 else -1 %}
    {% set item_end = (payment_terms or "").find("</li>", kseb_at) if item_at > 0 else -1 %}
    {% if item_end > 0 %}
    <div class="keep-section">
      <h2 class="section-title">Payment Terms</h2>
      <table class="kseb-table">
        <tr>
          <td class="proposal-content">{{ payment_terms[:item_at] | safe }}</ol></div></td>
          <td class="proposal-content">
            <div class="kseb-heading">{{ payment_terms[item_at:item_end] | striptags }}</div>
            <div class="ql-editor read-mode"><ol>{{ payment_terms[item_end + 5:] | safe }}
          </td>
        </tr>
      </table>
    </div>
    {% else %}
    {{ section("Payment Terms", payment_terms) }}
    {% endif %}

    {% set terms = frappe.db.get_value("Solar Proposal Content", {"title": ["like", "Terms & Conditions%"], "structure": structure, "enabled": 1}, "content") %}
    {{ section("Terms & Conditions", terms) }}
  </div>

  {# Always start the BOM on a new page after Terms & Conditions. #}
  <div class="proposal-remaining-pages">
    <table class="bom-table">
      <colgroup><col style="width:6%"><col style="width:18%"><col style="width:23%"><col style="width:41%"><col style="width:12%"></colgroup>
      <thead>
        <tr><th colspan="5" class="bom-title">Bill of Materials</th></tr>
        <tr><th>Sl No</th><th>Category</th><th>Item</th><th>Specification</th><th>Quantity</th></tr>
      </thead>
      <tbody>
      {# Repeat category on each row: rowspans across page breaks are unreliable. #}
      {% for item in doc.table_proposal_bom %}
        <tr>
          <td>{{ loop.index }}</td><td>{{ item.get("component_group") or "Materials" }}</td>
          <td>{{ item.get("component_label") or item.get("item_name") or item.item_code or "" }}{% if item.get("item_name") and item.component_label and item.item_name != item.component_label %}<br><span class="actual-item">{{ item.item_name }}</span>{% endif %}</td>
          <td>{{ (item.get("description") or "") | safe }}</td>
          <td>{{ "%g" | format(item.quantity or 0) }} {{ item.uom or "" }}</td>
        </tr>
      {% else %}<tr><td colspan="5">No material details recorded.</td></tr>
      {% endfor %}
      </tbody>
    </table>
    <p class="material-note">Material Quantity may vary according to the site conditions.</p>

    {% set notes = frappe.db.get_value("Solar Proposal Content", {"title": "Note", "enabled": 1}, "content") %}
    {{ section("Note", notes) }}
    {% set customer_scope = frappe.db.get_value("Solar Proposal Content", {"title": ["like", "Customer Scope%"], "structure": structure, "enabled": 1}, "content") %}
    {{ section("Customer Scope", customer_scope) }}
    {% set responsibilities = frappe.db.get_value("Solar Proposal Content", {"title": "Wahni Green Technologies - Responsibilities", "enabled": 1}, "content") %}
    {{ section("Wahni Green Technologies - Responsibilities", responsibilities) }}
    {% set why_wahni = frappe.db.get_value("Solar Proposal Content", {"title": "Why Wahni", "enabled": 1}, "content") %}
    {{ section("Why Wahni", why_wahni) }}
    {% set acc_details = frappe.db.get_value("Solar Proposal Content", {"title": "Company Account Details", "enabled": 1}, "content") %}
    <div class="proposal-closing keep-section">
      <p>We strive to keep our quotations clear and straightforward. Please feel free to reach out with any questions you may have.</p>
      {% if acc_details %}<h2 class="section-title">Company Account Details</h2><div class="proposal-content">{{ acc_details | safe }}</div>{% endif %}
      <div class="signature"><strong>For Wahni Green Technologies Pvt Ltd</strong><div class="signature-space"></div>Sooraj K<br>Sales Head</div>
    </div>
  </div>
</div>
